def zaslavsky(m: int, n: int) -> int:
    from math import comb
    return sum(comb(m, k) for k in range(min(m, n) + 1))

def deep_network_bound(widths: list, input_dim: int) -> int:
    from math import comb, prod
    def zaslavsky(m, n):
        return sum(comb(m, k) for k in range(min(m, n) + 1))
    return prod(zaslavsky(w, input_dim) for w in widths)

def zaslavsky_table(max_m: int, max_n: int) -> list:
    table = [[1]*(max_n+1) for _ in range(max_m+1)]
    for m in range(max_m):
        for n in range(max_n):
            table[m+1][n+1] = table[m][n+1] + table[m][n]
    return table
